import scrollLock from 'scroll-lock';
import { disablePageScroll, enablePageScroll } from 'scroll-lock/dist/scroll-lock.js';

export function screen6Tabs() {
  const titles = document.querySelectorAll('.screen6__title');
  const crosses = document.querySelectorAll('.screen6__cross');
  const descriptions = document.querySelectorAll('.screen6__description');

  descriptions.forEach(description => {
    if (window.innerWidth <= 1024) {
      description.classList.add('hidden');
    }
  })

  titles.forEach(title => {
    title.addEventListener('click', (e) => {
      if (window.innerWidth <= 1024){
        const item = title.closest('.screen6__item');
        const description = item.querySelector('.screen6__description');

        if (description.classList.contains('hidden')) {
          description.classList.remove('hidden');
        }

        description.classList.add('active');
        setTimeout( () => {
          disablePageScroll();
        }, 320)
      }
    })
  })

  if (crosses.length > 0) {
    crosses.forEach((cross) => {
      cross.addEventListener('click', (e) => {
        const item = cross.closest('.screen6__item');
        const description = item.querySelector('.screen6__description');

        if (description.classList.contains('active')) {
          description.classList.remove('active');
          enablePageScroll();
        }
      })
    })
  }

  window.addEventListener('resize', (e) => {
    descriptions.forEach(description => {
      if (window.innerWidth <= 1024) {
        description.classList.add('hidden');
      } else {
        description.classList.remove('hidden');
      }
      if (description.classList.contains('active')) {
          description.classList.remove('active');
          enablePageScroll();
      }
    })
  })
}